WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2000.5' AND Season = 2000);

INSERT INTO issues (IssueNum, IssueName, Season, Status, Rationale, RuleChangeText, Published)
SELECT '2000.6', 'Protections', 2000, 'Passed', 'The protection process would be changed so that one player may only be protected by the same team for three consecutive years. For every year above three that a player is protected it will cost an additional protection per additional year. (ie, a player protected for 5 years would cost the 1 normal protection, plus 2 additional protections.)  \n**The rule that passed is as follows: a player may be protected for three years at the current protection levels, after three years thier cost increases to two protection points, every three years after that thier protection cost increases by an additional protection (ie, a 7 year protected player costs 3 protections). All current players protected for two or more years will be considered to have two years of protections**', NULL, 1
WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2000.6' AND Season = 2000);

