INSERT INTO issues (IssueNum, IssueName, Season, Status, Rationale, RuleChangeText, Published)
SELECT '2000.9', 'Division Based Schedule', 2000, 'Open', 'Revise the current schedule formula (play everyone twice) so that every team plays the teams within thier division more frequently than teams outside the division. If we stay at 8 teams, this means everyone in your division 3 times, outside once except for one team that you play twice. For 10 teams, this means everyone in your division twice and outside once except for one team which you play twice. Finally, for 12 teams, everyone in your division twice and everyone out of your division once.', NULL, 1
WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2000.9' AND Season = 2000);

INSERT INTO issues (IssueNum, IssueName, Season, Status, Rationale, RuleChangeText, Published)
SELECT '2000.10', 'Missing Draft', 2000, 'Open', '**Missing draft equals two extra transactions**  \nThe are two proposals pertaining to missing the draft. The first would remove the extra protections clause for people who miss the draft. The second proposal would have any owner who misses the draft three consecutive years or four out of five years would be automaticlly removed from the league.', NULL, 1
WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2000.10' AND Season = 2000);

