INSERT INTO issues (IssueNum, IssueName, Season, Status, Rationale, RuleChangeText, Published)
SELECT '2001.5', 'Draft Order', 2001, 'Open', 'Change the method of determining draft order to the following. Teams that made the playoffs will draft in the last four positions in reverse order of finish. All non-playoff teams will be in the lottery with their lottery weight being the finishing place minus 4. The lottery will be used to determine the first three draft positions. All remaining positions will be filled in with the lottery teams not selected, in reverse order of finish. The draft order will remain the same for the entire draft.', 'Repeal ruled VI.D.2 and VI.D.4  \nAmend rule VI.D.3 to read the following:\n\n> The order is determined at least one week before the draft.  \n> &nbsp;&nbsp;&nbsp;a. Playoff teams will draft in the last four draft positions in reverse order of finish  \n> &nbsp;&nbsp;&nbsp;b. The first three positions will be determined by random, weighted draw of non-playoff teams  \n> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i. The fifth place team will recieve a weight of 1.  \n> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ii. Every other team will be weighted in reverse order of finish, recieving a weight of 1 more than the previous team.  \n> &nbsp;&nbsp;&nbsp;c. Remaining positions will be filled by non-playoff teams not selected in the lottery, in reverse order of finish.', 1
WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2001.5' AND Season = 2001);

