INSERT INTO issues (IssueNum, IssueName, Season, Status, Rationale, RuleChangeText, Published)
SELECT '2006.3', 'Revise Method for Determine Draft Day', 2006, 'Open', 'Change method for determing draft date to something less restrictive. The proposal simply selects the date which the most teams can attend. Teams are limited to selecting on 4 days they can\'t make it.', 'Change rule VI.E to read as follows:\n\n> The exact date of the draft will be selected to maximize the number of people able to attend.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1. No later than June 1st each team may submit to the commissioner a list of no more than four dates, meeting the criteria laid out in rule VI.B, in which they will be unable to attend the draft.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2. The commissioner shall within four days of the recipt of the lists determine and announce the draft date.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;a. The date in which the least number of teams said that they would be unable to attend shall be selected as draft day.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;b. In the event that two or more days are tied the following precidence shall be followed.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i. The weekend two weeks prior to the weekend that starts the NFL draft will have top priority.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ii. Among other weekends, the closer to the start of the NFL season will receive higher priority.  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;iii. Saturdays will have priority over Sundays.\n\n Current rule VI.E.3 should be attached to the end of this new rule.  \n Change the word \"sometime\" in rule VI.B.1 to \"a weekend day\"', 1
WHERE NOT EXISTS (SELECT 1 FROM issues WHERE IssueNum = '2006.3' AND Season = 2006);

