UPDATE issues SET RuleChangeText = 'Add rules V.B.3.e, V.B.4.e and V.B.7.f all reading:\n\n> Blocked Kick  \n>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;i. Each one = 3 pts' WHERE IssueNum = '2026.3' AND Season = 2026 AND (RuleChangeText IS NULL OR RuleChangeText = '');

